      { q: "कविता का संदेश तीन-चार वाक्यों में लिखिए।", a: "हमारा अनुभव जितना सीमित होता है, हमारी दुनिया भी उतनी ही छोटी लगती है। जब हम नई जगहें देखते हैं, सीखते हैं तो समझ बढ़ती है। हमें हमेशा सीखते और आगे बढ़ते रहना चाहिए।", marks: 3 },
      { q: "कविता के आधार पर चिड़िया की जीवन-यात्रा तीन वाक्यों में लिखिए।", a: "चिड़िया अंडे में थी तो वही उसका संसार था। फिर वह घोंसले में रही और बाद में पेड़ की डालियों पर निकली। अंत में वह पंख फैलाकर आसमान में उड़ी।", marks: 3 },
      { q: "गाँव की रीमा पहली बार रेलगाड़ी से अपने मामा के शहर गई। वहाँ ऊँची इमारतें, बड़े बाज़ार और अलग-अलग लोग देखकर वह हैरान रह गई।\n(i) रीमा का अनुभव कविता की किस बात से मिलता है?\n(ii) नया अनुभव हमें क्या देता है?\n(iii) आप कौन-सी नई जगह देखना चाहेंगे?", a: "(i) चिड़िया के आसमान में उड़कर संसार को बड़ा समझने की बात से।\n(ii) ज्ञान और समझ बढ़ती है तथा सोच का दायरा फैलता है।\n(iii) उत्तर अपना।", marks: 4, type: "case" }
