    written: [
      { q: "कालीबाई कहाँ की रहने वाली थी?", a: "कालीबाई राजस्थान के डूंगरपुर ज़िले के रास्तापाल गाँव की रहने वाली थी।", marks: 1 },
      { q: "स्कूल के दो अध्यापकों के नाम लिखिए।", a: "नानाभाई खाँट और सेंगाभाई।", marks: 1 },
      { q: "अंग्रेज़ सरकार रास्तापाल का स्कूल क्यों बंद करवाना चाहती थी?", a: "क्योंकि वहाँ गुप्त रूप से स्वतंत्रता आंदोलन से जुड़ी गतिविधियाँ चलती थीं। इसलिए सरकार ने स्कूल बंद करने को कहा।", marks: 2 },
      { q: "कालीबाई ने सिपाही की धमकी का क्या उत्तर दिया?", a: "सिपाही ने गोली मारने की धमकी दी, पर कालीबाई डरी नहीं। उसने निडर होकर कहा कि मारकर दिखाओ और रस्सियाँ काट दीं।", marks: 2 },
      { q: "'ढेर करना' और 'रफूचक्कर होना' मुहावरों का अर्थ लिखिए।", a: "ढेर करना – मार गिराना।\nरफूचक्कर होना – गायब हो जाना।", marks: 2 },
      { q: "कालीबाई के शहीद होने के बाद क्या हुआ?", a: "कालीबाई की मृत्यु की खबर सुनकर हज़ारों भील आदिवासी इकट्ठे हो गए। उन्होंने बिगुल बजाया और अंग्रेज़ों को घेर लिया। भीड़ देखकर सिपाही भाग गए।", marks: 3 },
      { q: "कालीबाई के चरित्र की तीन विशेषताएँ लिखिए।", a: "1. वह निडर और साहसी थी।\n2. वह अपने गुरुओं का आदर करती थी।\n3. वह देशभक्त थी और बलिदान के लिए तैयार रही।", marks: 3 },
      { q: "गाँव की सुनीता ने देखा कि कुछ लोग एक कमज़ोर बच्चे को परेशान कर रहे हैं। उसने बिना डरे उन्हें रोका और बड़ों को बुला लिया।\n(i) सुनीता ने कौन-सा गुण दिखाया?\n(ii) यह किस पात्र जैसा है?\n(iii) आप होते तो क्या करते?", a: "(i) साहस और दूसरों की मदद का गुण।\n(ii) कालीबाई जैसा।\n(iii) उत्तर अपना: मैं भी बड़ों को बुलाकर कमज़ोर की रक्षा करता/करती।", marks: 4, type: "case" }
    ]
