      { q: "चींटी हमें क्या सिखाती है?", a: "चींटी हमें सिखाती है कि मेहनत से हार नहीं माननी चाहिए। परिश्रम करते रहने पर सफलता अवश्य मिलती है।", marks: 2 },
      { q: "'काया' और 'विजय' के पर्यायवाची या विलोम लिखिए।", a: "काया – शरीर, देह\nविजय का विलोम – पराजय", marks: 2 },
      { q: "कविता से तुक वाले दो जोड़े शब्द छाँटिए।", a: "निर्भय – तन्मय\nकाया – माया", marks: 2 },
      { q: "कविता का संदेश अपने शब्दों में तीन वाक्यों में लिखिए।", a: "चींटी छोटी होकर भी निरंतर परिश्रम करती है। वह गिरने पर भी हार नहीं मानती। हमें भी उससे सीख लेकर लगातार मेहनत करनी चाहिए।", marks: 3 },
      { q: "मेहनत से सफलता कैसे मिलती है? किसी एक उदाहरण के साथ तीन वाक्यों में लिखिए।", a: "मेहनत करने से हम अपने लक्ष्य के निकट पहुँचते हैं। जैसे नियमित अभ्यास करने वाला विद्यार्थी परीक्षा में सफल होता है। बिना मेहनत के सफलता नहीं मिलती।", marks: 3 },
      { q: "अरुण ने कबड्डी की टीम में आने के लिए रोज़ सुबह अभ्यास किया। कई बार वह गिरा और चोट खाई, पर उसने अभ्यास नहीं छोड़ा। अंत में वह टीम में चुन लिया गया।\n(i) अरुण में कौन-सा गुण है?\n(ii) यह किस कविता की सीख से मिलता है?\n(iii) आप कोई लक्ष्य पाने के लिए क्या करेंगे?", a: "(i) लगन, परिश्रम और हिम्मत का गुण।\n(ii) 'चींटी' कविता की सीख से।\n(iii) उत्तर अपना: मैं नियमित अभ्यास और मेहनत करूँगा/करूँगी।", marks: 4, type: "case" }
